@Component("lot-entity-projector")
public class LotEntityProjector implements EntityProjector<Lot>{
		
	// core constructor
	public LotEntityProjector(ProjectorRegistry registry,
										LotRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Lot> getEntityClass() {
		return Lot.class;
	}

    /*
	 * Insert a Lot
	 * 
     * @param	entity Lot
     */
    public Lot create( Lot entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Lot
	 * 
     * @param	entity Lot
     */
    public Lot update( Lot entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Lot
	 * 
     * @param	id		UUID
     */
    public Lot delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Lot entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Sku
     * 
     * @param	parentId	UUID
     * @param	assignment 	StockKeepingUnit 
     * @return	Lot
     */
    public Lot assignSku( UUID parentId, StockKeepingUnit assignment ) {
	    LOGGER.info("assigning Sku as " + assignment.toString() );

	    Lot parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( StockKeepingUnit.class, assignment.getStockKeepingUnitId());

	    // ------------------------------------------
		// assign the Sku to the parent entity
		// ------------------------------------------ 
	    parentEntity.setSku( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Sku
	 * 
	 * @param	parentId		UUID
	 * @return	Lot
	 */
	public Lot unAssignSku( UUID parentId ) {
		Lot parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Sku on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Sku on the parent entithy
		// ------------------------------------------     
	    parentEntity.setSku(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the InventoryItems
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Lot
     */
    public Lot addToInventoryItems( UUID parentId, InventoryItem addTo ) {
	    LOGGER.info("handling AssignInventoryItemsToLotEvent - " );
	    
	    Lot parentEntity = repository.findById(parentId).get();
	    InventoryItem child = registry.project( InventoryItem.class, addTo.getInventoryItemId());
	    
	    parentEntity.getInventoryItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the InventoryItems
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Lot
     */
	public Lot removeFromInventoryItems( UUID parentId, InventoryItem removeFrom ) {
	    LOGGER.info("handling RemoveInventoryItemsFromLotEvent " );
	
	    Lot parentEntity = repository.findById(parentId).get();
	    InventoryItem child = registry.project( InventoryItem.class, removeFrom.getInventoryItemId());
	    
	    parentEntity.getInventoryItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Lot via an FindLotQuery
     * @return 	query	FindLotQuery
     */
    @SuppressWarnings("unused")
    public Lot find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Lot - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Lots
     *
     * @param	query	FindAllLotQuery 
     * @return 	List<Lot> 
     */
    @SuppressWarnings("unused")
    public List<Lot> findAll( FindAllLotQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Lot - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final LotRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(LotEntityProjector.class.getName());

}
